import Foundation
import SQLite3

nonisolated enum DictionaryError: Error, Equatable {
    case databaseNotFound
    case openFailed(String)
    case unsupportedSchemaVersion(Int)
    case queryFailed(String)
}

/// Read-only access to the dictionary database generated by
/// scripts/build_dictionary.py.
///
/// An actor so searches run off the main thread and the SQLite connection is
/// only ever used from one place at a time.
actor SQLiteDictionary: DictionarySearching {
    static let schemaVersion = 1

    // Only used from the actor's own methods and from deinit, which can't run
    // concurrently with them; `nonisolated(unsafe)` just lets deinit close it.
    nonisolated(unsafe) private let db: OpaquePointer

    init(url: URL) throws(DictionaryError) {
        guard FileManager.default.fileExists(atPath: url.path) else {
            throw .databaseNotFound
        }
        var handle: OpaquePointer?
        guard sqlite3_open_v2(url.path, &handle, SQLITE_OPEN_READONLY | SQLITE_OPEN_NOMUTEX, nil) == SQLITE_OK,
              let handle else {
            let message = handle.map { String(cString: sqlite3_errmsg($0)) } ?? "unknown error"
            sqlite3_close(handle)
            throw .openFailed(message)
        }

        let version = Self.userVersion(of: handle)
        guard version == Self.schemaVersion else {
            sqlite3_close(handle)
            throw .unsupportedSchemaVersion(version)
        }
        db = handle
    }

    /// Opens the database shipped in the app bundle.
    static func bundled(in bundle: Bundle = .main) throws(DictionaryError) -> SQLiteDictionary {
        guard let url = bundle.url(forResource: "Dictionary", withExtension: "sqlite") else {
            throw .databaseNotFound
        }
        return try SQLiteDictionary(url: url)
    }

    deinit {
        sqlite3_close(db)
    }

    func search(_ query: String, limit: Int) throws -> [DictionaryEntry] {
        let key = DictionarySearchQuery.normalize(query)
        guard !key.isEmpty, limit > 0 else { return [] }

        // Rough ranking: exact match, then prefix, then anywhere in the word;
        // within each, single words before phrases/idioms, easier vocabulary
        // first, then shorter words.
        let entries = try rows(
            """
            SELECT id, word, homonym_number, lexical_unit, part_of_speech,
                   origin, pronunciation, vocabulary_level
            FROM entries
            WHERE instr(search_key, ?1) > 0
            ORDER BY
                CASE WHEN search_key = ?1 THEN 0
                     WHEN substr(search_key, 1, length(?1)) = ?1 THEN 1
                     ELSE 2 END,
                CASE lexical_unit WHEN '단어' THEN 0 ELSE 1 END,
                CASE vocabulary_level WHEN '초급' THEN 0 WHEN '중급' THEN 1 WHEN '고급' THEN 2 ELSE 3 END,
                length(search_key),
                search_key,
                homonym_number
            LIMIT ?2
            """,
            bind: [.text(key), .integer(Int64(limit))]
        ) { statement in
            DictionaryEntry(
                id: sqlite3_column_int64(statement, 0),
                word: Self.text(statement, 1) ?? "",
                homonymNumber: Int(sqlite3_column_int(statement, 2)),
                lexicalUnit: Self.text(statement, 3),
                partOfSpeech: Self.text(statement, 4),
                origin: Self.text(statement, 5),
                pronunciation: Self.text(statement, 6),
                vocabularyLevel: Self.text(statement, 7),
                senses: []
            )
        }
        guard !entries.isEmpty else { return [] }

        let placeholders = Array(repeating: "?", count: entries.count).joined(separator: ", ")
        let senses = try rows(
            """
            SELECT entry_id, sense_order, definition, english_lemma, english_definition
            FROM senses
            WHERE entry_id IN (\(placeholders))
            ORDER BY entry_id, sense_order
            """,
            bind: entries.map { .integer($0.id) }
        ) { statement in
            (
                entryID: sqlite3_column_int64(statement, 0),
                sense: DictionaryEntry.Sense(
                    order: Int(sqlite3_column_int(statement, 1)),
                    definition: Self.text(statement, 2) ?? "",
                    englishLemma: Self.text(statement, 3),
                    englishDefinition: Self.text(statement, 4)
                )
            )
        }
        let sensesByEntry = Dictionary(grouping: senses, by: \.entryID)

        return entries.map { entry in
            DictionaryEntry(
                id: entry.id,
                word: entry.word,
                homonymNumber: entry.homonymNumber,
                lexicalUnit: entry.lexicalUnit,
                partOfSpeech: entry.partOfSpeech,
                origin: entry.origin,
                pronunciation: entry.pronunciation,
                vocabularyLevel: entry.vocabularyLevel,
                senses: sensesByEntry[entry.id, default: []].map(\.sense)
            )
        }
    }

    // MARK: - SQLite helpers

    private enum Binding {
        case text(String)
        case integer(Int64)
    }

    private func rows<Row>(
        _ sql: String,
        bind bindings: [Binding],
        map: (OpaquePointer) -> Row
    ) throws(DictionaryError) -> [Row] {
        var statement: OpaquePointer?
        guard sqlite3_prepare_v2(db, sql, -1, &statement, nil) == SQLITE_OK, let statement else {
            throw .queryFailed(String(cString: sqlite3_errmsg(db)))
        }
        defer { sqlite3_finalize(statement) }

        for (offset, binding) in bindings.enumerated() {
            let index = Int32(offset + 1)
            switch binding {
            case .text(let value):
                sqlite3_bind_text(statement, index, value, -1, Self.transient)
            case .integer(let value):
                sqlite3_bind_int64(statement, index, value)
            }
        }

        var result: [Row] = []
        while true {
            switch sqlite3_step(statement) {
            case SQLITE_ROW:
                result.append(map(statement))
            case SQLITE_DONE:
                return result
            default:
                throw .queryFailed(String(cString: sqlite3_errmsg(db)))
            }
        }
    }

    private static func text(_ statement: OpaquePointer, _ column: Int32) -> String? {
        sqlite3_column_text(statement, column).map { String(cString: $0) }
    }

    private static func userVersion(of db: OpaquePointer) -> Int {
        var statement: OpaquePointer?
        guard sqlite3_prepare_v2(db, "PRAGMA user_version", -1, &statement, nil) == SQLITE_OK else { return -1 }
        defer { sqlite3_finalize(statement) }
        return sqlite3_step(statement) == SQLITE_ROW ? Int(sqlite3_column_int(statement, 0)) : -1
    }

    /// Tells SQLite to copy bound strings, since Swift may free them first.
    private static let transient = unsafeBitCast(-1, to: sqlite3_destructor_type.self)
}
